USystemDamageComponent::USystemDamageComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer), SubsystemDamageThreshold(0.1f) {
}

void USystemDamageComponent::BeginPlay() {
	Super::BeginPlay();
}

void USystemDamageComponent::InitializeFromShip(const TArray<FName>& SystemNames) {
	SubsystemHealth.Add(TEXT("Engines"), 100.0f);
	SubsystemMaxHealth.Add(TEXT("Engines"), 100.0f);
	SubsystemHealth.Add(TEXT("Weapons"), 100.0f);
	SubsystemMaxHealth.Add(TEXT("Weapons"), 100.0f);
	SubsystemHealth.Add(TEXT("LifeSupport"), 100.0f);
	SubsystemMaxHealth.Add(TEXT("LifeSupport"), 100.0f);

	for (const FName& SysName : SystemNames) {
		if (!SubsystemHealth.Contains(SysName)) {
			SubsystemHealth.Add(SysName, 100.0f);
			SubsystemMaxHealth.Add(SysName, 100.0f);
		}
	}
}

void USystemDamageComponent::ApplySystemDamage(float IncomingHullDamage) {
	float SubsystemDamage = IncomingHullDamage * SubsystemDamageThreshold;
	for (TPair<FName, float>& Pair : SubsystemHealth) {
		if (Pair.Value > 0.0f) {
			float DamageToApply = FMath::Min(SubsystemDamage, Pair.Value);
			Pair.Value -= DamageToApply;
			SubsystemDamage -= DamageToApply;
			if (SubsystemDamage <= 0.0f) break;
		}
	}
}

void USystemDamageComponent::RepairSubsystem(FName SystemName, float Amount) {
	if (SubsystemHealth.Contains(SystemName)) {
		float NewHealth = FMath::Min(SubsystemHealth[SystemName] + Amount, SubsystemMaxHealth[SystemName]);
		SubsystemHealth[SystemName] = NewHealth;
	}
}

float USystemDamageComponent::GetSubsystemHealth(FName SystemName) const {
	if (SubsystemHealth.Contains(SystemName)) return SubsystemHealth[SystemName];
	return 0.0f;
}

ESubsystemStatus USystemDamageComponent::GetSubsystemStatus(FName SystemName) const {
	float Health = GetSubsystemHealth(SystemName);
	float MaxHealth = 100.0f;
	if (SubsystemMaxHealth.Contains(SystemName)) MaxHealth = SubsystemMaxHealth[SystemName];
	float Percent = MaxHealth > 0.0f ? Health / MaxHealth : 1.0f;

	if (Percent <= 0.0f) return ESubsystemStatus::Destroyed;
	if (Percent < 0.25f) return ESubsystemStatus::Critical;
	if (Percent < 0.5f) return ESubsystemStatus::Damaged;
	return ESubsystemStatus::Operational;
}
